// Recomputes the answers of elements/practice-exam-4.md (PTF SPEC.md §7.1):
// word counts, quotations, sentence analysis, forms and points of the paper.

// BEGIN latin.js (generated by checks/lib/inline.mjs, do not edit)
// --- latin.js: shared Latin helpers for the answer checks of this bundle ---
// Source of truth: checks/lib/latin.js. `node checks/lib/inline.mjs` copies it
// into every checks/<element>.js between the BEGIN/END markers (check scripts
// cannot import). Forms are written without macrons, as in the Matura.
//
// Nouns and adjectives are generated from their dictionary entry, verbs from
// their principal parts; `parse(form, lexicon)` lists every reading of a form,
// so a check tests a claim ("omnibus is dative or ablative plural") against
// the generated paradigm instead of against the stored answer.

const CASES = ["nom", "gen", "dat", "acc", "abl"];

// Endings per declension: [sg nom..abl], [pl nom..abl]; "*" = the nominative given.
const NOUN_ENDINGS = {
  a: [["a", "ae", "ae", "am", "a"], ["ae", "arum", "is", "as", "is"]],
  o: [["us", "i", "o", "um", "o"], ["i", "orum", "is", "os", "is"]],
  er: [["*", "i", "o", "um", "o"], ["i", "orum", "is", "os", "is"]],
  on: [["um", "i", "o", "um", "o"], ["a", "orum", "is", "a", "is"]],
  k: [["*", "is", "i", "em", "e"], ["es", "um", "ibus", "es", "ibus"]],
  ki: [["*", "is", "i", "em", "e"], ["es", "ium", "ibus", "es", "ibus"]],
  kn: [["*", "is", "i", "*", "e"], ["a", "um", "ibus", "a", "ibus"]],
  kin: [["*", "is", "i", "*", "i"], ["ia", "ium", "ibus", "ia", "ibus"]],
  u: [["us", "us", "ui", "um", "u"], ["us", "uum", "ibus", "us", "ibus"]],
  e: [["es", "ei", "ei", "em", "e"], ["es", "erum", "ebus", "es", "ebus"]],
};

/** All forms of a noun: { nom: "rex", stem: "reg", decl: "k", gender: "m" } → [{form, case, number, gender}]. */
function decline(n) {
  const out = [];
  const ends = NOUN_ENDINGS[n.decl];
  ["sg", "pl"].forEach((number, ni) => ends[ni].forEach((e, ci) => {
    const form = e === "*" ? n.nom : n.stem + e;
    out.push({ lemma: n.lemma ?? n.nom, form, case: CASES[ci], number, gender: n.gender });
  }));
  return out;
}

/** Adjectives: { lemma: "bonus", stem: "bon", type: "ao" } or { lemma: "omnis", stem: "omn", type: "i2", nomM?, nomN? }. */
function declineAdj(a) {
  const st = a.stem;
  if (a.type === "ao" || a.type === "aoer") {
    const nomM = a.type === "aoer" ? a.lemma : st + "us";
    return [
      ...decline({ lemma: a.lemma, nom: nomM, stem: st, decl: a.type === "aoer" ? "er" : "o", gender: "m" }),
      ...decline({ lemma: a.lemma, stem: st, decl: "a", gender: "f" }),
      ...decline({ lemma: a.lemma, stem: st, decl: "on", gender: "n" }),
    ];
  }
  // third declension, i-stem (omnis, omne; acer, acris, acre; felix, felicis; ingens, ingentis)
  const nomM = a.nomM ?? st + "is", nomF = a.nomF ?? nomM, nomN = a.nomN ?? (a.type === "i1" ? nomM : st + "e");
  return [
    ...decline({ lemma: a.lemma, nom: nomM, stem: st, decl: "ki", gender: "m" }).map(abl_i),
    ...decline({ lemma: a.lemma, nom: nomF, stem: st, decl: "ki", gender: "f" }).map(abl_i),
    ...decline({ lemma: a.lemma, nom: nomN, stem: st, decl: "kin", gender: "n" }),
  ];
  function abl_i(f) { return f.case === "abl" && f.number === "sg" ? { ...f, form: st + "i" } : f; }
}

// Participles: present (amans, amantis) like a one-ending i-stem adjective but abl sg -e
// when used as participle; PPP/PFA like bonus.
function presentParticiple(nomSg, stem, lemma) {
  return declineAdj({ lemma, stem, type: "i1", nomM: nomSg }).map((f) =>
    f.case === "abl" && f.number === "sg" ? { ...f, form: stem + "e" } : f);
}

// ---------- verbs ----------
// v = { lemma: "amare", conj: "1"|"2"|"3"|"3i"|"4", pres: "ama"|"mone"|"reg"|"capi"|"audi", perf: "amav", ppp: "amat", dep: false }
const PERS = [["1", "sg"], ["2", "sg"], ["3", "sg"], ["1", "pl"], ["2", "pl"], ["3", "pl"]];
const ACT = ["m", "s", "t", "mus", "tis", "nt"], PAS = ["r", "ris", "tur", "mur", "mini", "ntur"];

function conjugate(v) {
  const out = [];
  const add = (forms, tense, mood, voice) => forms.forEach((form, i) =>
    out.push({ lemma: v.lemma, form, person: PERS[i][0], number: PERS[i][1], tense, mood, voice }));
  const c = v.conj, s = v.pres, root = c === "3i" ? s.slice(0, -1) : s; // capi → cap
  // present indicative
  const presA = {
    "1": [root.slice(0, -1) + "o", s + "s", s + "t", s + "mus", s + "tis", s + "nt"],
    "2": [s + "o", s + "s", s + "t", s + "mus", s + "tis", s + "nt"],
    "3": [s + "o", s + "is", s + "it", s + "imus", s + "itis", s + "unt"],
    "3i": [s + "o", root + "is", root + "it", root + "imus", root + "itis", s + "unt"],
    "4": [s + "o", s + "s", s + "t", s + "mus", s + "tis", s + "unt"],
  }[c];
  const presP = {
    "1": [root.slice(0, -1) + "or", s + "ris", s + "tur", s + "mur", s + "mini", s + "ntur"],
    "2": [s + "or", s + "ris", s + "tur", s + "mur", s + "mini", s + "ntur"],
    "3": [s + "or", s + "eris", s + "itur", s + "imur", s + "imini", s + "untur"],
    "3i": [s + "or", root + "eris", root + "itur", root + "imur", root + "imini", s + "untur"],
    "4": [s + "or", s + "ris", s + "tur", s + "mur", s + "mini", s + "untur"],
  }[c];
  // imperfect
  const impfStem = { "1": s + "ba", "2": s + "ba", "3": s + "eba", "3i": s + "eba", "4": s + "eba" }[c];
  const impA = ACT.map((e, i) => impfStem + (i === 0 ? "m" : e));
  const impP = PAS.map((e) => impfStem + e);
  // future
  let futA, futP;
  if (c === "1" || c === "2") {
    futA = ["bo", "bis", "bit", "bimus", "bitis", "bunt"].map((e) => s + e);
    futP = ["bor", "beris", "bitur", "bimur", "bimini", "buntur"].map((e) => s + e);
  } else {
    const fs = c === "3" ? s : s; // reg-, capi-, audi-
    futA = ["am", "es", "et", "emus", "etis", "ent"].map((e) => fs + e);
    futP = ["ar", "eris", "etur", "emur", "emini", "entur"].map((e) => fs + e);
  }
  // present subjunctive
  const sj = { "1": root.slice(0, -1) + "e", "2": s + "a", "3": s + "a", "3i": s + "a", "4": s + "a" }[c];
  const psA = ACT.map((e) => sj + e), psP = PAS.map((e) => sj + e);
  // imperfect subjunctive = present infinitive active + endings
  const inf = presentInfinitive(v, "act");
  const isA = ACT.map((e) => inf.slice(0, -1) + "e" + e), isP = PAS.map((e) => inf.slice(0, -1) + "e" + e);
  const active = !v.dep;
  if (active) {
    add(presA, "present", "ind", "act"); add(impA, "imperfect", "ind", "act"); add(futA, "future", "ind", "act");
    add(psA, "present", "subj", "act"); add(isA, "imperfect", "subj", "act");
  }
  if (!v.noPassive) {
    const voice = v.dep ? "dep" : "pass";
    add(presP, "present", "ind", voice); add(impP, "imperfect", "ind", voice); add(futP, "future", "ind", voice);
    add(psP, "present", "subj", voice); add(isP, "imperfect", "subj", voice);
  }
  if (active && v.perf) {
    const p = v.perf;
    add(["i", "isti", "it", "imus", "istis", "erunt"].map((e) => p + e), "perfect", "ind", "act");
    add(["eram", "eras", "erat", "eramus", "eratis", "erant"].map((e) => p + e), "pluperfect", "ind", "act");
    add(["ero", "eris", "erit", "erimus", "eritis", "erint"].map((e) => p + e), "future perfect", "ind", "act");
    add(["erim", "eris", "erit", "erimus", "eritis", "erint"].map((e) => p + e), "perfect", "subj", "act");
    add(["issem", "isses", "isset", "issemus", "issetis", "issent"].map((e) => p + e), "pluperfect", "subj", "act");
  }
  if (v.ppp) {
    // perfect passive / deponent: participle + form of esse (written as two words)
    const voice = v.dep ? "dep" : "pass";
    const parts = { perfect: { ind: ["sum", "es", "est", "sumus", "estis", "sunt"], subj: ["sim", "sis", "sit", "simus", "sitis", "sint"] },
      pluperfect: { ind: ["eram", "eras", "erat", "eramus", "eratis", "erant"], subj: ["essem", "esses", "esset", "essemus", "essetis", "essent"] } };
    for (const [tense, moods] of Object.entries(parts)) for (const [mood, aux] of Object.entries(moods))
      aux.forEach((x, i) => {
        const pl = i >= 3, endings = pl ? ["i", "ae", "a"] : ["us", "a", "um"];
        endings.forEach((e) => out.push({ lemma: v.lemma, form: v.ppp + e + " " + x, person: PERS[i][0], number: PERS[i][1], tense, mood, voice }));
      });
  }
  // imperatives and infinitives
  const imp = { "1": s, "2": s, "3": s + "e", "3i": root + "e", "4": s }[c];
  const impPl = { "1": s + "te", "2": s + "te", "3": s + "ite", "3i": root + "ite", "4": s + "te" }[c];
  if (active) {
    out.push({ lemma: v.lemma, form: v.imp ?? imp, person: "2", number: "sg", tense: "present", mood: "imp", voice: "act" });
    out.push({ lemma: v.lemma, form: impPl, person: "2", number: "pl", tense: "present", mood: "imp", voice: "act" });
    out.push({ lemma: v.lemma, form: inf, tense: "present", mood: "inf", voice: "act" });
    if (v.perf) out.push({ lemma: v.lemma, form: v.perf + "isse", tense: "perfect", mood: "inf", voice: "act" });
  }
  if (!v.noPassive) out.push({ lemma: v.lemma, form: presentInfinitive(v, "pass"), tense: "present", mood: "inf", voice: v.dep ? "dep" : "pass" });
  if (v.dep) {
    out.push({ lemma: v.lemma, form: c === "3" ? s + "ere" : c === "3i" ? root + "ere" : s + "re", person: "2", number: "sg", tense: "present", mood: "imp", voice: "dep" });
  }
  return out;
}

function presentInfinitive(v, voice) {
  const c = v.conj, s = v.pres, root = c === "3i" ? s.slice(0, -1) : s;
  if (voice === "act") return { "1": s + "re", "2": s + "re", "3": s + "ere", "3i": root + "ere", "4": s + "re" }[c];
  return { "1": s + "ri", "2": s + "ri", "3": s + "i", "3i": root + "i", "4": s + "ri" }[c];
}

// esse and posse (irregular, active only)
function conjugateSum(prefix = "", lemma = "esse") {
  const P = (f) => (prefix === "pot" ? (f[0] === "s" ? "pos" + f : "pot" + f) : prefix + f);
  const out = [];
  const add = (forms, tense, mood) => forms.forEach((f, i) => out.push({ lemma, form: P(f), person: PERS[i][0], number: PERS[i][1], tense, mood, voice: "act" }));
  add(["sum", "es", "est", "sumus", "estis", "sunt"], "present", "ind");
  add(["eram", "eras", "erat", "eramus", "eratis", "erant"], "imperfect", "ind");
  if (prefix !== "pot") add(["ero", "eris", "erit", "erimus", "eritis", "erunt"], "future", "ind");
  else add(["ero", "eris", "erit", "erimus", "eritis", "erunt"], "future", "ind");
  add(["sim", "sis", "sit", "simus", "sitis", "sint"], "present", "subj");
  if (prefix === "pot") ["possem", "posses", "posset", "possemus", "possetis", "possent"].forEach((f, i) => out.push({ lemma, form: f, person: PERS[i][0], number: PERS[i][1], tense: "imperfect", mood: "subj", voice: "act" }));
  else add(["essem", "esses", "esset", "essemus", "essetis", "essent"], "imperfect", "subj");
  const perf = prefix === "pot" ? "potu" : "fu";
  ["i", "isti", "it", "imus", "istis", "erunt"].forEach((e, i) => out.push({ lemma, form: perf + e, person: PERS[i][0], number: PERS[i][1], tense: "perfect", mood: "ind", voice: "act" }));
  ["issem", "isses", "isset", "issemus", "issetis", "issent"].forEach((e, i) => out.push({ lemma, form: perf + e, person: PERS[i][0], number: PERS[i][1], tense: "pluperfect", mood: "subj", voice: "act" }));
  out.push({ lemma, form: prefix === "pot" ? "posse" : "esse", tense: "present", mood: "inf", voice: "act" });
  return out;
}

// ---------- pronouns ----------
// Tables per gender: [sg nom gen dat acc abl], [pl nom gen dat acc abl].
const PRONOUNS = {
  is: { m: [["is", "eius", "ei", "eum", "eo"], ["ei", "eorum", "eis", "eos", "eis"]], f: [["ea", "eius", "ei", "eam", "ea"], ["eae", "earum", "eis", "eas", "eis"]], n: [["id", "eius", "ei", "id", "eo"], ["ea", "eorum", "eis", "ea", "eis"]] },
  hic: { m: [["hic", "huius", "huic", "hunc", "hoc"], ["hi", "horum", "his", "hos", "his"]], f: [["haec", "huius", "huic", "hanc", "hac"], ["hae", "harum", "his", "has", "his"]], n: [["hoc", "huius", "huic", "hoc", "hoc"], ["haec", "horum", "his", "haec", "his"]] },
  ille: { m: [["ille", "illius", "illi", "illum", "illo"], ["illi", "illorum", "illis", "illos", "illis"]], f: [["illa", "illius", "illi", "illam", "illa"], ["illae", "illarum", "illis", "illas", "illis"]], n: [["illud", "illius", "illi", "illud", "illo"], ["illa", "illorum", "illis", "illa", "illis"]] },
  ipse: { m: [["ipse", "ipsius", "ipsi", "ipsum", "ipso"], ["ipsi", "ipsorum", "ipsis", "ipsos", "ipsis"]], f: [["ipsa", "ipsius", "ipsi", "ipsam", "ipsa"], ["ipsae", "ipsarum", "ipsis", "ipsas", "ipsis"]], n: [["ipsum", "ipsius", "ipsi", "ipsum", "ipso"], ["ipsa", "ipsorum", "ipsis", "ipsa", "ipsis"]] },
  qui: { m: [["qui", "cuius", "cui", "quem", "quo"], ["qui", "quorum", "quibus", "quos", "quibus"]], f: [["quae", "cuius", "cui", "quam", "qua"], ["quae", "quarum", "quibus", "quas", "quibus"]], n: [["quod", "cuius", "cui", "quod", "quo"], ["quae", "quorum", "quibus", "quae", "quibus"]] },
};

/** All forms of a pronoun ("is", "hic", "ille", "ipse", "qui"), like decline(). */
function pronoun(lemma) {
  const out = [];
  for (const [gender, t] of Object.entries(PRONOUNS[lemma]))
    ["sg", "pl"].forEach((number, ni) => t[ni].forEach((form, ci) => out.push({ lemma, form, case: CASES[ci], number, gender })));
  return out;
}

/** Participles of a verb: present active (PPA), perfect passive (PPP), future active (PFA). */
function participles(v) {
  const out = [];
  const c = v.conj, s = v.pres;
  if (!v.noPPA) {
    const ps = { "1": s + "nt", "2": s + "nt", "3": s + "ent", "3i": s + "ent", "4": s + "ent" }[c];
    const nom = ps.slice(0, -1) + "s";
    out.push(...presentParticiple(nom, ps, v.lemma).map((f) => ({ ...f, participle: "PPA", tense: "present", voice: v.dep ? "dep" : "act" })));
  }
  if (v.ppp) {
    out.push(...declineAdj({ lemma: v.lemma, stem: v.ppp, type: "ao" }).map((f) => ({ ...f, participle: v.dep ? "PPDep" : "PPP", tense: "perfect", voice: v.dep ? "dep" : "pass" })));
    out.push(...declineAdj({ lemma: v.lemma, stem: v.ppp + "ur", type: "ao" }).map((f) => ({ ...f, participle: "PFA", tense: "future", voice: "act" })));
  }
  return out;
}

/** Gerundive (and the gerund, which has the neuter singular forms gen to abl). */
function gerundive(v) {
  const c = v.conj, s = v.pres;
  const st = { "1": s + "nd", "2": s + "nd", "3": s + "end", "3i": s + "end", "4": s + "end" }[c];
  return declineAdj({ lemma: v.lemma, stem: st, type: "ao" }).map((f) => ({ ...f, gerundive: true }));
}

/** Every reading of `form` among the paradigms in `lexicon` (an array of paradigms, i.e. arrays of readings). */
function parse(form, lexicon) {
  const f = form.toLowerCase().trim();
  return lexicon.flat().filter((r) => r.form === f);
}

/** Does some reading of `form` have all properties of `want`? */
function canBe(form, lexicon, want) {
  return parse(form, lexicon).some((r) => Object.entries(want).every(([k, v]) => r[k] === v));
}

/** Can two forms agree in case, number and gender (KNG-Kongruenz)? */
function agree(a, b, lexicon) {
  const ra = parse(a, lexicon), rb = parse(b, lexicon);
  return ra.some((x) => rb.some((y) => x.case && x.case === y.case && x.number === y.number && x.gender === y.gender));
}

// ---------- texts ----------
const words = (t) => String(t).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").match(/[a-zäöüß]+/g) ?? [];
const wordCount = (t) => String(t).split(/\s+/).filter((w) => /[\p{L}\d]/u.test(w)).length;

/** Is `quote` a passage of `text` (same words in the same order, ignoring case and punctuation)? */
function quotes(text, quote) {
  const t = " " + words(text).join(" ") + " ", q = " " + words(quote).join(" ") + " ";
  return q.trim().length > 0 && t.includes(q);
}

/** Do the parts use every word of the sentence, each part a set of its words (HS/GS/sK analysis)? */
function covers(sentence, parts) {
  const all = words(sentence), used = parts.flatMap((p) => words(p));
  const count = (xs) => xs.reduce((m, w) => m.set(w, (m.get(w) ?? 0) + 1), new Map());
  const ca = count(all), cu = count(used);
  return [...ca].every(([w, n]) => (cu.get(w) ?? 0) >= n) && used.every((w) => ca.has(w));
}
// --- end of latin.js ---
// END latin.js

const TEXT_A = `In colonia Hipponensi pueri cotidie in mari natabant; qui longissime
a litore processerat, victor habebatur. Quodam die puer quidam audacior
ceteris longius natavit. Subito delphinus ei occurrit et nunc ante eum,
nunc post eum natabat. Deinde puerum timentem dorso sustulit et primo in
altum portavit, mox ad litus reduxit. Haec fama per totam urbem celeriter
divulgata est. Postero die homines ad litus concurrerunt, ut ipsi
spectaculum viderent. Delphinus rursus apparuit et puerum, qui iam non
timebat, iterum vexit. Cum multi cives eum blande vocarent, animal etiam
tangi se patiebatur. Sed magistratus, quod tot homines ex agris venerant et
urbem sumptibus gravabant, delphinum occidi iusserunt. Ita animal mite,
quod pueros amaverat, periit.`;
const TEXT_B = `Libenter ex iis, qui a te veniunt, cognovi familiariter te cum servis
tuis vivere. Hoc prudentiam tuam, hoc eruditionem decet. Servi sunt.
Immo homines. Servi sunt. Immo contubernales. Servi sunt. Immo
humiles amici. Servi sunt. Immo conservi, si cogitaveris tantundem in
utrosque licere fortunae. Cogita istum, quem servum
tuum vocas, ex isdem seminibus ortum eodem frui caelo, aeque spirare,
aeque vivere, aeque mori! Ostende, quis non sit servus: alius libidini
servit, alius avaritiae, alius ambitioni, omnes timori. Sic cum inferiore
vivas, quemadmodum tecum superiorem velis vivere.`;

const lex = [
  conjugate({ lemma: "procedere", conj: "3", pres: "proced", perf: "process", noPassive: true }),
  conjugate({ lemma: "divulgare", conj: "1", pres: "divulga", perf: "divulgav", ppp: "divulgat" }),
  conjugate({ lemma: "vivere", conj: "3", pres: "viv", perf: "vix", noPassive: true }),
  conjugate({ lemma: "velle", conj: "3", pres: "vel", noPassive: true }), // only for vivas-like checks below
  decline({ lemma: "puer", nom: "puer", stem: "puer", decl: "er", gender: "m" }), decline({ lemma: "fama", stem: "fam", decl: "a", gender: "f" }),
  decline({ lemma: "magistratus", stem: "magistrat", decl: "u", gender: "m" }),
  declineAdj({ lemma: "audax", stem: "audacior", type: "i1", nomM: "audacior", nomN: "audacius" }),
  participles({ lemma: "timere", conj: "2", pres: "time" }),
  declineAdj({ lemma: "divulgatus", stem: "divulgat", type: "ao" }),
];

fact("translation text: 111 words; interpretation text: about 87 words", () => { ptf.assert(wordCount(TEXT_A) === 111, `A has ${wordCount(TEXT_A)}`); ptf.assert(Math.abs(wordCount(TEXT_B) - 87) <= 3, `B has ${wordCount(TEXT_B)}`); return true; });
fact("points: 12 + 6 + 6 + 6 + 6 = 36 and ten tasks = 24", () => 12 + 6 * 4 === 36 && [3, 3, 3, 3, 2, 1, 2, 2, 2, 3].reduce((a, b) => a + b, 0) === 24);
fact("marking key forms", () =>
  canBe("processerat", lex, { tense: "pluperfect" }) && agree("audacior", "puer", lex) && agree("timentem", "puerum", lex) &&
  canBe("timentem", lex, { case: "acc", number: "sg", participle: "PPA" }) && agree("divulgata", "fama", lex) && canBe("magistratus", lex, { case: "nom", number: "pl" }));
fact("SE passages quote text A", () => ["In colonia", "qui longissime", "Quodam die", "Haec fama", "Postero die", "Delphinus rursus", "Cum multi", "Sed magistratus, quod", "delphinum occidi iusserunt", "Ita animal"].every((p) => quotes(TEXT_A, p)));

check("translation", (q) => { ptf.assert(wordCount(q.sample_answer) > 100, "full sample translation"); return true; });

check("it1-loanwords", () => ["spir", "cogn", "prudent"].map((stem) => { const w = words(TEXT_B).filter((x) => x.startsWith(stem)); ptf.assert(w.length === 1, stem); return w[0]; }));

check("it2-word-formation", () => {
  ptf.assert(quotes(TEXT_B, "eruditionem") && quotes(TEXT_B, "familiariter") && quotes(TEXT_B, "conservi"), "words in the text");
  ptf.assert("erudire".replace(/re$/, "") + "tio" === "eruditio" && "familiaris".replace(/is$/, "i") + "ter" === "familiariter" && "con" + "servi" === "conservi", "parts rebuild the words");
  return true;
});

check("it3-structure", (q) => {
  const S = "Libenter ex iis, qui a te veniunt, cognovi familiariter te cum servis tuis vivere.";
  const rows = q.sample_answer.split("; ").map((r) => r.replace(/^(HS|GS|sK)\s+/, ""));
  ptf.assert(covers(S, rows) && quotes(S, rows[1]) && quotes(S, rows[2]), "complete analysis, GS and sK contiguous");
  return true;
});

check("it4-quotations", (q) => { ptf.assert(q.rubric.map((r) => r.replace(/^\(\w\)\s*/, "")).every((r) => quotes(TEXT_B, r)), "all quotations are in the text"); return true; });

check("it5-style", (q) => {
  const anaphora = (t) => { const p = t.split(",").map((x) => words(x)); return p.length >= 2 && p.every((x) => x[0] === p[0][0]); };
  const [a, b] = q.sample_answer.split("; ");
  ptf.assert(quotes(TEXT_B, a) && quotes(TEXT_B, b) && anaphora(a) && anaphora(b), "two quoted anaphoras");
  return true;
});

check("it7-compare", (q) => { ptf.assert(wordCount(q.sample_answer) <= 66); return true; });
check("it8-position", (q) => { ptf.assert(wordCount(q.sample_answer) <= 66); return true; });
check("it9-guiding-questions", (q) => { ptf.assert(wordCount(q.sample_answer) <= 66 && quotes(TEXT_B, "alius libidini servit alius avaritiae alius ambitioni omnes timori")); return true; });
check("it10-creative", (q) => { ptf.assert(wordCount(q.sample_answer) <= 110); return true; });
